const results = $json.results || [];

const leads = [];

function cleanLinkedInUrl(url) {
  if (!url || typeof url !== 'string') return '';

  // Remove markdown link formatting if present
  const markdownMatch = url.match(/\((https?:\/\/[^)]+)\)/);
  if (markdownMatch) {
    url = markdownMatch[1];
  }

  // Remove trailing slash
  url = url.trim().replace(/\/+$/, '');

  // Convert localized LinkedIn domains to www.linkedin.com
  url = url.replace(
    /^https?:\/\/([a-z]{2}\.)?linkedin\.com/i,
    'https://www.linkedin.com'
  );

  return url;
}

function cleanLocation(profile) {
  const city = String(profile.city || '').trim();
  const countryCode = String(profile.country_code || '').trim();

  if (!city) return '';

  // If ScrapeGraphAI already returned a complete location,
  // don't append the country again.
  const normalizedCity = city.toLowerCase();

  const countryMap = {
    US: 'United States',
    IN: 'India',
    GB: 'United Kingdom',
    CA: 'Canada',
    AU: 'Australia',
    AE: 'United Arab Emirates',
    SG: 'Singapore'
  };

  const country = countryMap[countryCode] || countryCode;

  if (
    country &&
    normalizedCity.endsWith(country.toLowerCase())
  ) {
    return city;
  }

  return country ? `${city}, ${country}` : city;
}

for (const result of results) {
  let profile = {};

  try {
    let content = result.content;

    if (typeof content === 'string') {
      content = content.trim();

      // Remove markdown code fences
      content = content
        .replace(/^```json\s*/i, '')
        .replace(/^```\s*/i, '')
        .replace(/\s*```$/i, '')
        .trim();

      profile = JSON.parse(content);
    } else {
      profile = content;
    }

    // ScrapeGraphAI may return an array
    if (Array.isArray(profile)) {
      profile = profile[0] || {};
    }

    // Safety check
    if (!profile || typeof profile !== 'object') {
      profile = {};
    }

  } catch (error) {
    profile = {};
  }

  const rawTitle = result.title || '';

  // Extract name/title from search result title
  const titleParts = rawTitle
    .split(' - ')
    .map(part => part.trim())
    .filter(Boolean);

  const name =
    profile.name ||
    titleParts[0] ||
    '';

  const title =
    profile.position ||
    (
      titleParts.length > 1
        ? titleParts.slice(1).join(' - ')
        : rawTitle
    );

  const company =
    profile.current_company?.name ||
    '';

  const location = cleanLocation(profile);

  const posts = Array.isArray(profile.posts)
    ? profile.posts.map(post => ({
        title: post.title || '',
        content:
          post.attribution ||
          post.content ||
          '',
        url:
          post.link ||
          post.url ||
          ''
      }))
    : [];

  const linkedinUrl = cleanLinkedInUrl(
    profile.url ||
    result.url ||
    ''
  );

  leads.push({
    name: String(name).trim(),
    title: String(title).trim(),
    company: String(company).trim(),
    location,
    about: String(profile.about || '').trim(),
    linkedin_url: linkedinUrl,
    posts
  });
}

return leads.map(lead => ({
  json: lead
}));

const inputItems = $input.all();

const searchData = $('02 — Prepare Search Filters').first().json;

const jobTitle = String(
  searchData.job_title ??
  searchData.jobTitle ??
  ''
).trim().toLowerCase();

const keyword = String(
  searchData.keywords ??
  searchData.keyword ??
  searchData.industry ??
  ''
).trim().toLowerCase();

const location = String(
  searchData.location ?? ''
).trim().toLowerCase();

function normalize(value) {
  return String(value ?? '')
    .toLowerCase()
    .trim();
}

/*
 * Broad geographic regions.
 * These are used only for validation after ScrapeGraphAI
 * has already performed the actual search.
 */
const regions = {
  europe: [
    'albania','andorra','austria','belarus','belgium','bosnia',
    'bulgaria','croatia','cyprus','czech republic','denmark',
    'estonia','finland','france','germany','greece','hungary',
    'iceland','ireland','italy','kosovo','latvia','liechtenstein',
    'lithuania','luxembourg','malta','moldova','monaco',
    'montenegro','netherlands','north macedonia','norway',
    'poland','portugal','romania','russia','san marino',
    'serbia','slovakia','slovenia','spain','sweden','switzerland',
    'ukraine','united kingdom','uk','vatican'
  ],

  asia: [
    'afghanistan','armenia','azerbaijan','bahrain','bangladesh',
    'bhutan','brunei','cambodia','china','georgia','india',
    'indonesia','iran','iraq','israel','japan','jordan',
    'kazakhstan','kuwait','kyrgyzstan','laos','lebanon',
    'malaysia','maldives','mongolia','myanmar','nepal',
    'north korea','oman','pakistan','philippines','qatar',
    'saudi arabia','singapore','south korea','sri lanka',
    'syria','taiwan','tajikistan','thailand','timor-leste',
    'turkey','turkmenistan','united arab emirates','uae',
    'uzbekistan','vietnam','yemen'
  ],

  africa: [
    'algeria','angola','benin','botswana','burkina faso',
    'burundi','cameroon','cape verde','central african republic',
    'chad','comoros','congo','djibouti','egypt','eritrea',
    'eswatini','ethiopia','gabon','gambia','ghana','guinea',
    'kenya','lesotho','liberia','libya','madagascar','malawi',
    'mali','mauritania','mauritius','morocco','mozambique',
    'namibia','niger','nigeria','rwanda','senegal','seychelles',
    'sierra leone','somalia','south africa','south sudan',
    'sudan','tanzania','togo','tunisia','uganda','zambia',
    'zimbabwe'
  ],

  'north america': [
    'canada','united states','usa','mexico','greenland',
    'costa rica','panama','guatemala','belize','honduras',
    'el salvador','nicaragua','cuba','jamaica',
    'dominican republic','haiti','bahamas'
  ],

  'south america': [
    'argentina','bolivia','brazil','chile','colombia',
    'ecuador','guyana','paraguay','peru','suriname',
    'uruguay','venezuela'
  ],

  'oceania': [
    'australia','new zealand','fiji','papua new guinea',
    'samoa','tonga','vanuatu','solomon islands',
    'micronesia','palau','kiribati','tuvalu','nauru'
  ]
};

const worldwideTerms = [
  'worldwide',
  'world',
  'global',
  'anywhere',
  'everywhere',
  'all countries',
  'international'
];

function locationMatches(leadLocation) {
  const candidate = normalize(leadLocation);

  // Empty location input means no geographic restriction.
  if (!location) return true;

  // Worldwide/global search means no geographic restriction.
  if (worldwideTerms.includes(location)) return true;

  if (!candidate) return false;

  // Direct match: country, city, state, etc.
  if (candidate.includes(location)) {
    return true;
  }

  // Broad region / continent match.
  const countries = regions[location];

  if (countries) {
    return countries.some(country =>
      candidate.includes(country)
    );
  }

  /*
   * If the user enters an unfamiliar broad geographic term,
   * don't automatically reject every ScrapeGraph result.
   * ScrapeGraphAI already used the user's location in discovery.
   */
  return true;
}

function titleMatches(lead) {
  if (!jobTitle) return true;

  const text = [
    lead.name,
    lead.title,
    lead.about,
    lead.company
  ]
    .map(normalize)
    .join(' ');

  return text.includes(jobTitle);
}

function keywordMatches(lead) {
  if (!keyword) return true;

  const postsText = Array.isArray(lead.posts)
    ? lead.posts
        .map(post =>
          `${post?.title ?? ''} ${post?.content ?? ''}`
        )
        .join(' ')
    : '';

  const text = [
    lead.name,
    lead.title,
    lead.company,
    lead.about,
    postsText
  ]
    .map(normalize)
    .join(' ');

  return text.includes(keyword);
}

const seen = new Set();
const filtered = [];

for (const item of inputItems) {
  const lead = item.json;

  const linkedinUrl = normalize(lead.linkedin_url);

  // LinkedIn URL is the minimum useful identity for a lead.
  if (!linkedinUrl || seen.has(linkedinUrl)) {
    continue;
  }

  const titleMatch = titleMatches(lead);
  const locationMatch = locationMatches(lead.location);
  const keywordMatch = keywordMatches(lead);

  if (
    titleMatch &&
    locationMatch &&
    keywordMatch
  ) {
    seen.add(linkedinUrl);

    filtered.push({
      json: {
        ...lead,

        // Explicitly preserve these fields for downstream nodes.
        name: lead.name ?? '',
        title: lead.title ?? '',
        company: lead.company ?? '',
        location: lead.location ?? '',
        about: lead.about ?? '',
        linkedin_url: lead.linkedin_url ?? '',
        posts: lead.posts ?? []
      }
    });
  }
}

return filtered;

const leads = $input.all();

const urls = leads
  .map(item => item.json.linkedin_url)
  .filter(url => typeof url === 'string' && url.trim() !== '');

return [
  {
    json: {
      urls
    }
  }
];

const geminiItems = $input.all();

const apifyItems = $('If').all();
const originalLeads = $('05 — Filter Leads').all();

function normalizeUrl(value) {
  return String(value || '')
    .toLowerCase()
    .trim()
    .replace(/\/$/, '');
}

return geminiItems.map((item, index) => {
  const rawText = item.json?.content?.parts?.[0]?.text;

  if (!rawText) {
    throw new Error(`Gemini response missing for item ${index + 1}`);
  }

  let generated;

  try {
    generated = JSON.parse(rawText);
  } catch (error) {
    throw new Error(
      `Invalid Gemini JSON for item ${index + 1}: ${rawText}`
    );
  }

  const apifyLead = apifyItems[index]?.json || {};

  const apifyLinkedIn = normalizeUrl(
    apifyLead.linkedinUrl ||
    apifyLead.linkedin_url ||
    apifyLead.linkedin
  );

  // Find the original clean ScrapeGraph lead
  const originalLead =
    originalLeads.find(item => {
      const url = normalizeUrl(item.json?.linkedin_url);
      return url && url === apifyLinkedIn;
    })?.json || {};

  const email =
    apifyLead.emails?.[0]?.email ||
    apifyLead.email ||
    '';

  const name =
    originalLead.name ||
    apifyLead.firstName ||
    apifyLead.first_name ||
    `${apifyLead.firstName || ''} ${apifyLead.lastName || ''}`.trim();

  const title =
    originalLead.title ||
    apifyLead.headline ||
    apifyLead.title ||
    '';

  const company =
    originalLead.company ||
    apifyLead.company ||
    apifyLead.companyName ||
    '';

  const location =
    typeof originalLead.location === 'string'
      ? originalLead.location
      : '';

  const linkedin =
    originalLead.linkedin_url ||
    apifyLead.linkedinUrl ||
    apifyLead.linkedin_url ||
    '';

  return {
    json: {
      name,
      title,
      company,
      location,
      email,
      linkedin_url: linkedin,
      subject: generated.subject || '',
      body: generated.body || ''
    }
  };
});

return items.map(item => {
  const row = item.json;

  return {
    json: {
      "Name": row["Name"] || "",
      "Email": row["Email"] || "",
      "Company": row["Company"] || "",
      "LinkedIn URL": row["LinkedIn URL"] || "",
      "Subject": row["Subject"] || "",
      "Body": row["Body"] || "",
      "Gmail Draft ID": row["Gmail Draft ID"] || "",
      "Status": row["Status"] || "",
      "Drafted At": row["Drafted At"] || "",
      "Sent At": row["Sent At"] || "",
      "Cancelled At": row["Cancelled At"] || ""
    }
  };
});

const apifyLeads = $input.all();
const originalLeads = $('05 — Filter Leads').all();

return apifyLeads.map(item => {
  const apifyLead = item.json || {};

  const apifyUrl = String(
    apifyLead.linkedinUrl ||
    apifyLead.linkedin_url ||
    ''
  )
    .toLowerCase()
    .replace(/\/$/, '');

  const originalLead = originalLeads.find(originalItem => {
    const originalUrl = String(
      originalItem.json.linkedin_url || ''
    )
      .toLowerCase()
      .replace(/\/$/, '');

    return originalUrl === apifyUrl;
  })?.json || {};

  return {
    json: {
      Name:
        originalLead.name ||
        `${apifyLead.firstName || ''} ${apifyLead.lastName || ''}`.trim(),

      Title:
        originalLead.title ||
        originalLead.headline ||
        apifyLead.headline ||
        apifyLead.title ||
        '',

      Email: 'Email not found',

      Company:
        originalLead.company ||
        apifyLead.company ||
        apifyLead.companyName ||
        '',

      Location:
        originalLead.location ||
        apifyLead.location ||
        '',

      'LinkedIn URL':
        originalLead.linkedin_url ||
        apifyLead.linkedinUrl ||
        apifyLead.linkedin_url ||
        '',

      Subject: '',
      Body: '',
      'Gmail Draft ID': '',

      Status: 'Email not found',

      'Drafted At': '',
      'Sent At': '',
      'Cancelled At': ''
    }
  };
});

const items = $input.all();
const webhook = $('05 — Webhook — Draft Action').first().json.body || {};

return items.map(item => {
  const row = item.json || {};

  const draftId = String(
    row['Gmail Draft ID'] || webhook.draftId || ''
  ).trim();

  const email = String(row.Email || '').trim();

  const subject = String(
    webhook.subject ?? row.Subject ?? ''
  );

  const body = String(
    webhook.body ?? row.Body ?? ''
  );

  if (!draftId) {
    throw new Error('Missing Gmail Draft ID');
  }

  if (!email) {
    throw new Error('Missing recipient email');
  }

  const mime = [
    `To: ${email}`,
    `Subject: ${subject}`,
    'MIME-Version: 1.0',
    'Content-Type: text/plain; charset="UTF-8"',
    'Content-Transfer-Encoding: 8bit',
    '',
    body
  ].join('\r\n');

  const raw = Buffer
    .from(mime, 'utf8')
    .toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/g, '');

  return {
    json: {
      ...row,
      editDraftId: draftId,
      editSubject: subject,
      editBody: body,
      gmailRaw: raw
    }
  };
});

const items = $input.all();

return [
  {
    json: {
      success: true,
      leads: items.map(item => item.json)
    }
  }
];

const drafts = $input.all();
const leads = $('09 — Prepare Lead Email').all();

return drafts.map((draftItem, index) => {
  const lead = leads[index]?.json || {};
  const draft = draftItem.json || {};

  return {
    json: {
      Name: lead.name || '',
      Title: lead.title || '',
      Email: lead.email || '',
      Company: lead.company || '',
      Location: lead.location || '',
      'LinkedIn URL': lead.linkedin_url || '',
      Subject: lead.subject || '',
      Body: lead.body || '',

      'Gmail Draft ID': draft.id || '',

      Status: 'Drafted',
      'Drafted At': new Date().toISOString(),
      'Sent At': '',
      'Cancelled At': ''
    }
  };
});
